  return relative.length === 0 ? '.' : relative.replace(/\\/g, '/');
}

export function readPackageOutDir(env: NodeJS.ProcessEnv): string {
  return readStringEnv('EXTFN_PACKAGE_OUT_DIR', {
    defaultValue: 'dist/packages',
    env,
  });
}

